template:
use std::fmt::Display;

fn duplicate_and_print<T: ⟦bounds_slot⟧>(item: &T) -> String {
    let copy = (*item).clone();
    format!("{copy}")
}

fn main() {
    let val = ⟦val_slot⟧;
    println!("{}", duplicate_and_print(&val));
}

tests:
#[test]
fn duplicates_and_prints() {
    let s = String::from("test");
    assert_eq!(duplicate_and_print(&s), "test");
}
